////////////////////////////////
// RA Stepper configuration (OAT)
// See supported stepper values. Change according to the steppers you are using
// Using the NEMA 17, 1.8°/step stepper for RA
#define RA_STEPPER_TYPE STEPPER_TYPE_ENABLED
#define RA_STEPPER_SPR	400

// Using the TMC2209-UART driver for RA stepper motor
#define RA_DRIVER_TYPE DRIVER_TYPE_TMC2209_UART

// Define some RA stepper motor settings
#define RA_MOTOR_CURRENT_RATING        900 // mA
#define RA_OPERATING_CURRENT_SETTING   90 // %
#define RA_STEPPER_ACCELERATION        10000
// TODO: (MWK) TMC2209 Datasheet indicates that stall guard may not be accurate at speeds less than 1RPS (section 11.5)
// That would mean for a 200 step/revolution motor and 32 microsteps/step we would need a homing speed of 6400
// With a base stepper frequency of 2kHz, we can't generate 6.4kHz steps/sec.
// I've changed the base frequency from 500uS to 50uS (20kHz) which allows for 200 or 400 steps/revolution at 32 microsteps/step and
// some head room.
#define RA_SLEW_MICROSTEPPING          16
#define RA_TRACKING_MICROSTEPPING      256
#define RA_STEPPER_SPEED               RA_STEPPER_SPR * RA_SLEW_MICROSTEPPING   // 1 RPS

// Range is 0-255 - and is multiplied by 2 in the TMC driver, then compared to SG_RESULT: If SG_RESULT falls *below* this
// 2x value, it is considered a stall. 
#define RA_STALL_VALUE                 90   // SG_RESULT < 180 after TSTEP is < 400
#define RA_TCOOLTHRS                   400

// Is it going the wrong way?
#define RA_INVERT_DIR  1

#ifdef NEW_STEPPER_LIB
  #define RA_SLEWING_ACCELERATION_DEG   2.0  // deg/s/s
  #define RA_SLEWING_SPEED_DEG          2.0  // deg/s
#endif

// Track immediately after boot
#define TRACK_ON_BOOT 1

// Define limits for RA... 
#define RA_LIMIT_LEFT     5.5f
#define RA_LIMIT_RIGHT    6.5f
#define RA_TRACKING_LIMIT 6.75f // can't quite get to 7h...

// Using the 16 tooth gear (recommended) for RA belt
#define RA_PULLEY_TEETH 16

