#define DEC_STEPPER_ACCELERATION       10000
#define DEC_SLEW_MICROSTEPPING         16
#define DEC_GUIDE_MICROSTEPPING        256
#define DEC_STEPPER_SPEED              DEC_STEPPER_SPR * DEC_SLEW_MICROSTEPPING
#define DEC_STALL_VALUE                90   // SG_RESULT < 180 after TSTEP is < 400
#define DEC_TCOOLTHRS                  400  // Velocities below which to disable StallGuard and Coolstep

